head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.gAcptNo;
scwin.gIsurCd;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    fn_Search();
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !불성실지정--;
목록검색(유가증권);
사용자;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    txb_TotalCnt.setValue("총건수 : ");
    let bndListStat = scwin.getChkValue(chb_ListStatCd);
    if (bndListStat === "0") {
        bndListStat = "2"; // 채권공시 해제법인

    }
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // 채권매매거래정지
        let url_list = "/UnfaithfulDesign.do?method=trdHaltBond&inputMessageId=TRHALTBOND_IN" + "&outputMessageId=TRHALTBOND_OUT";
        let url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&BND_LIST_STAT=" + bndListStat + "&FORM_CD=91680" + "&SCREN_ID=" + 'ULDSTF35810.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

        // 그리드의 데이타 조회
        dts_trdhaltbond_list.DataID = encodeURI(url_list + url_cond);
        dts_trdhaltbond_list.reset();
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        // 채권매매거래정지해제
        let url_list = "/UnfaithfulDesign.do?method=trdHaltBond&inputMessageId=TRHALTBOND_IN" + "&outputMessageId=TRHALTBOND_OUT";
        let url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&BND_LIST_STAT=" + bndListStat + "&FORM_CD=91681" + "&SCREN_ID=" + 'ULDSTF35810.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

        // 그리드의 데이타 조회
        dts_trdhaltbond_list_2.DataID = encodeURI(url_list + url_cond);
        dts_trdhaltbond_list_2.reset();
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        // 채권매매거래정지 및 해제
        let url_list = "/UnfaithfulDesign.do?method=trdHaltBond&inputMessageId=TRHALTBOND_IN" + "&outputMessageId=TRHALTBOND_OUT";
        let url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&BND_LIST_STAT=" + bndListStat + "&FORM_CD=91682" + "&SCREN_ID=" + 'ULDSTF35810.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

        // 그리드의 데이타 조회
        dts_trdhaltbond_list_3.DataID = encodeURI(url_list + url_cond);
        dts_trdhaltbond_list_3.reset();
    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        // 채권매매거래정지 및 상장폐지
        let url_list = "/UnfaithfulDesign.do?method=trdHaltBond&inputMessageId=TRHALTBOND_IN" + "&outputMessageId=TRHALTBOND_OUT";
        let url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&BND_LIST_STAT=" + bndListStat + "&FORM_CD=91683" + "&SCREN_ID=" + 'ULDSTF35810.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

        // 그리드의 데이타 조회
        dts_trdhaltbond_delist.DataID = encodeURI(url_list + url_cond);
        dts_trdhaltbond_delist.reset();
    }
};

/**
 * @method
 * @name setContnIdList
 * @description 그리드에서 클릭 row의 변수셋팅 매매거래정지
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnIdList = function(obj) {
    scwin.gAcptNo = dts_trdhaltbond_list.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_trdhaltbond_list.getCellData(Number(obj), "ISUR_CD");
};

