/**
 * @method
 * @name grd_trdhistbond_list_OnDblClick
 * @description grd_trdhistbond_list 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_trdhistbond_list_OnDblClick = async function(row, colid) {
    scwin.setContnIdList(row);
    if (colid === "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "BND_ISU_NM") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF35810.xml');
    } else if (colid === "DISCLS_PUBL_DDTM") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF35810.xml');
    } else if (colid === "TRD_HALT_PD_CONTN") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF35810.xml');
    }
};

